#!/usr/bin/env bash
# 셸에는 값을 돌려주는 자리가 없다. return 은 0~255 뿐이라 답을 못 싣는다.
# 그래서 반환은 echo 로 내보내고 부르는 쪽이 $() 로 받는다.
_out() {
    if [ -z "${1##*[!A-Za-z0-9_]*}" ]; then echo $(( $1 ))
    elif [ -z "${1##*[!0-9]*}" ]; then eval "echo \"\${$1[*]}\""
    else echo "$1"; fi
}
# 셸은 인자를 값이 아니라 글자로 받는다. 부르는 쪽이 넘긴 'b' 나 '(a % b)'
# 를 함수가 스스로 셈해야 하는데, local 은 이름을 하나씩 가려 나가므로
# 나중 인자를 셈할 때는 앞 인자가 이미 새 값으로 덮여 있다. 그래서 이름을
# 붙이기 전에 인자를 통째로 먼저 굳힌다 — 부르는 쪽 값으로.
_args() {
    local _o= _x
    for _x in "$@"; do
        case "$_x" in
            *,*)        _o="$_o ${_x// /}" ;;
            *[!0-9-]*)  _o="$_o $(( $_x ))" ;;
            *)          _o="$_o $_x" ;;
        esac
    done
    echo $_o
}

